339	/// Extract mnemonic entries from `; "name" opcode=N type=T` comment lines.
340	/// Returns set of (name, opcode).
341	fn mnemonic_entries(src: &str) -> BTreeSet<(String, u32)> {
342	    let mut set = BTreeSet::new();
343	    for line in src.lines() {
344	        let trimmed = line.trim();
345	        if let Some(rest) = trimmed.strip_prefix("; \"") {
346	            if let Some(quote_end) = rest.find('"') {
347	                let name = &rest[..quote_end];
348	                if let Some(opcode_part) = rest.find("opcode=") {
349	                    let after = &rest[opcode_part + 7..];
350	                    let num_str: String =
351	                        after.chars().take_while(|c| c.is_ascii_digit()).collect();
352	                    if let Ok(opcode) = num_str.parse::<u32>() {
353	                        set.insert((name.to_string(), opcode));
354	                    }
355	                }
356	            }
357	        }
358	    }
359	    set
360	}
