/// Encoding format for p-code instructions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Encoding {
    /// 1 byte: [op]
    None,
    /// 2 bytes: [op, imm8]
    Imm8,
    /// 4 bytes: [op, lo, mid, hi]
    Imm24,
    /// 5 bytes: [op, d8, lo, mid, hi]
    D8A24,
    /// 3 bytes: [op, d8, o8]
    D8O8,
}

impl Encoding {
    /// Total instruction size in bytes (including opcode byte).
    pub const fn size(self) -> usize {
        match self {
            Encoding::None => 1,
            Encoding::Imm8 => 2,
            Encoding::Imm24 => 4,
            Encoding::D8A24 => 5,
            Encoding::D8O8 => 3,
        }
    }
}

/// P-code opcodes. Values match pvm.s ground truth.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum Opcode {
    // Stack operations (0x00-0x06)
    Halt = 0x00,
    Push = 0x01,
    PushS = 0x02,
    Dup = 0x03,
    Drop = 0x04,
    Swap = 0x05,
    Over = 0x06,

    // Arithmetic (0x10-0x15)
    Add = 0x10,
    Sub = 0x11,
    Mul = 0x12,
    Div = 0x13,
    Mod = 0x14,
    Neg = 0x15,

    // Logic (0x16-0x1B)
    And = 0x16,
    Or = 0x17,
    Xor = 0x18,
    Not = 0x19,
    Shl = 0x1A,
    Shr = 0x1B,

    // Comparison (0x20-0x25)
    Eq = 0x20,
    Ne = 0x21,
    Lt = 0x22,
    Le = 0x23,
    Gt = 0x24,
    Ge = 0x25,

    // Control flow (0x30-0x36)
    Jmp = 0x30,
    Jz = 0x31,
    Jnz = 0x32,
    Call = 0x33,
    Ret = 0x34,
    Calln = 0x35,
    Trap = 0x36,

    // Local / Global / Nonlocal access (0x40-0x4B)
    Enter = 0x40,
    Leave = 0x41,
    Loadl = 0x42,
    Storel = 0x43,
    Loadg = 0x44,
    Storeg = 0x45,
    Addrl = 0x46,
    Addrg = 0x47,
    Loada = 0x48,
    Storea = 0x49,
    Loadn = 0x4A,
    Storen = 0x4B,

    // Memory indirect (0x50-0x53)
    Load = 0x50,
    Store = 0x51,
    Loadb = 0x52,
    Storeb = 0x53,

    // System calls (0x60)
    Sys = 0x60,

    // Memory block operations (0x70-0x72)
    Memcpy = 0x70,
    Memset = 0x71,
    Memcmp = 0x72,

    // Indirect jump (0x73)
    JmpInd = 0x73,
}

impl Opcode {
    /// Return the encoding format for this opcode.
    pub const fn encoding(self) -> Encoding {
        match self {
            // NONE encoding (1 byte)
            Opcode::Halt
            | Opcode::Dup
            | Opcode::Drop
            | Opcode::Swap
            | Opcode::Over
            | Opcode::Add
            | Opcode::Sub
            | Opcode::Mul
            | Opcode::Div
            | Opcode::Mod
            | Opcode::Neg
            | Opcode::And
            | Opcode::Or
            | Opcode::Xor
            | Opcode::Not
            | Opcode::Shl
            | Opcode::Shr
            | Opcode::Eq
            | Opcode::Ne
            | Opcode::Lt
            | Opcode::Le
            | Opcode::Gt
            | Opcode::Ge
            | Opcode::Leave
            | Opcode::Load
            | Opcode::Store
            | Opcode::Loadb
            | Opcode::Storeb
            | Opcode::Memcpy
            | Opcode::Memset
            | Opcode::Memcmp
            | Opcode::JmpInd => Encoding::None,

            // IMM8 encoding (2 bytes)
            Opcode::PushS
            | Opcode::Ret
            | Opcode::Trap
            | Opcode::Enter
            | Opcode::Loadl
            | Opcode::Storel
            | Opcode::Addrl
            | Opcode::Loada
            | Opcode::Storea
            | Opcode::Sys => Encoding::Imm8,

            // IMM24 encoding (4 bytes)
            Opcode::Push
            | Opcode::Jmp
            | Opcode::Jz
            | Opcode::Jnz
            | Opcode::Call
            | Opcode::Loadg
            | Opcode::Storeg
            | Opcode::Addrg => Encoding::Imm24,

            // D8_A24 encoding (5 bytes): calln depth8 addr24
            Opcode::Calln => Encoding::D8A24,

            // D8_O8 encoding (3 bytes): loadn/storen depth8 off8
            Opcode::Loadn | Opcode::Storen => Encoding::D8O8,
        }
    }

    /// Instruction size in bytes.
    pub const fn size(self) -> usize {
        self.encoding().size()
    }

    /// Look up an opcode by its mnemonic string.
    pub fn from_mnemonic(name: &str) -> Option<Opcode> {
        match name {
            "halt" => Some(Opcode::Halt),
            "push" => Some(Opcode::Push),
            "push_s" => Some(Opcode::PushS),
