            "over" => Some(Opcode::Over),
            "add" => Some(Opcode::Add),
            "sub" => Some(Opcode::Sub),
            "mul" => Some(Opcode::Mul),
            "div" => Some(Opcode::Div),
            "mod" => Some(Opcode::Mod),
            "neg" => Some(Opcode::Neg),
            "eq" => Some(Opcode::Eq),
            "ne" => Some(Opcode::Ne),
            "lt" => Some(Opcode::Lt),
            "le" => Some(Opcode::Le),
