let unit_info = unit_name.map(|name| {
    let exports = export_names
        .iter()
        .map(|(sym_name, nargs)| {
            let offset = symbols
                .get(sym_name)
                .map(|s| s.value)
                .unwrap_or(0);
            ExportEntry {
                name: sym_name.clone(),
                offset,
                nargs: *nargs,
            }
        })
        .collect();
    let imports = extern_slots
        .iter()
        .enumerate()
        .map(|(slot, (proc_name, uname))| ImportEntry {
