fn assemble_hello() {
    let source = include_str!("../../vm/hello.spc");
    let result = assemble(source);
    assert!(result.errors.is_empty(), "errors: {:?}", result.errors);
    assert_eq!(result.entry_point, 0, "main should be at offset 0");
